input.command:
cd /tmp/pr
for mode in success help fmt hours; do
  case $mode in
    success) A=(--a 12:30 --b x --c y);;
    help) A=(--help);;
    fmt) A=(--a 99:99 --b x --c y);;
    hours) A=(--a 24:00 --b x --c y);;
  esac
  /workspace/dataset/test4_executable "${A[@]}" >/dev/full 2>e_$mode.txt; echo "$mode devfull exit=$?  stderr_bytes=$(wc -c <e_$mode.txt)"
done
echo "=== stderr success ==="; cat -A e_success.txt
echo "=== stderr help ==="; cat -A e_help.txt
echo "=== stderr fmt ==="; cat -A e_fmt.txt

cd /tmp/pr
cat > drv.pl <<'EOF'
#!/usr/bin/perl
use strict; use warnings; use Encode qw(encode);
# args: label, then a spec for --a built from tokens:
#   c:HEXCP  -> unicode codepoint
#   s:TEXT   -> literal ascii text
my $lbl = shift @ARGV;
my $val = '';
for my $t (@ARGV) {
  if ($t =~ /^c:(.+)$/) { $val .= encode('UTF-8', chr(hex($1))); }
  elsif ($t =~ /^s:(.*)$/s) { $val .= $1; }
  elsif ($t =~ /^b:(.+)$/) { $val .= pack('H*', $1); }
}
my $exe = '/workspace/dataset/test4_executable';
my $pid = fork();
if ($pid == 0) {
  open(STDOUT, '>', '/tmp/pr/po.txt') or die; open(STDERR, '>', '/tmp/pr/pe.txt') or die;
  exec { $exe } ($exe, '--a', $val, '--b', 'x', '--c', 'y') or die;
}
waitpid($pid, 0);
my $rc = $? >> 8;
my $se = do { local $/; open(my $f, '<', '/tmp/pr/pe.txt'); <$f> // '' };
my $so = -s '/tmp/pr/po.txt';
my $k = $rc == 0 ? 'OK' : ($se =~ /Invalid time format/ ? 'FMT' : ($se =~ /Invalid number of hours/ ? 'HOURS' : ($rc==2 ? 'ARGERR' : "OTHER($rc)")));
printf("%-38s %-6s rc=%d so=%d\n", $lbl, $k, $rc, $so);
EOF
chmod +x drv.pl
echo "--- sanity ---"
perl drv.pl "10:30 ascii" s:10:30
perl drv.pl "2+U+0664 ArabicIndic4" s:2 c:0664 s::00
perl drv.pl "2+U+0663 ArabicIndic3" s:2 c:0663 s::00
echo "--- Unicode version skew probes (value 4 slot => HOURS iff Nd) ---"
perl drv.pl "U+11F54 Kawi (Uni 15.0)"      s:2 c:11F54 s::00
perl drv.pl "U+1E4F4 NagMundari (Uni 15.0)" s:2 c:1E4F4 s::00
perl drv.pl "U+11BF4 Sunuwar (Uni 16.0)"   s:2 c:11BF4 s::00
perl drv.pl "U+16D74 KiratRai (Uni 16.0)"  s:2 c:16D74 s::00
perl drv.pl "U+16134 GurungKhema (Uni16.0)" s:2 c:16134 s::00
perl drv.pl "U+1E5F5 OlOnal (Uni 16.0)"    s:2 c:1E5F5 s::00
perl drv.pl "U+105BB unassigned"           s:2 c:105BB s::00

cd /tmp/pr && node --input-type=module -e "
const re=/\p{Nd}/u;
const cps=[0x0664,0x11F54,0x1E4F4,0x11BF4,0x16D74,0x16134,0x1E5F5,0x1D7D8,0x1D7CD];
for(const c of cps) console.log('U+'+c.toString(16).toUpperCase().padStart(4,'0'), 'JS_Nd='+re.test(String.fromCodePoint(c)));
console.log('---JS traps---');
console.log('/^[0-2]\\\\d\$/.test(\"2٤\") =', /^[0-2]\d\$/.test('2٤'));
console.log('/^[0-2]\\\\p{Nd}\$/u.test(\"2٤\") =', /^[0-2]\p{Nd}\$/u.test('2٤'));
console.log('JS \$ before trailing LF: /^[0-2]\\\\d:[0-5]\\\\d\$/.test(\"10:30\\\\n\") =', /^[0-2]\d:[0-5]\d\$/.test('10:30\n'));
console.log('JS \$ with m flag on 10:30\\\\n\\\\n =', /^[0-2]\d:[0-5]\d\$/m.test('10:30\n\n'));
console.log('parseInt(\"2٤\") =', parseInt('2٤'), ' Number(\"2٤\") =', Number('2٤'));
console.log('Number(\"30\\\\n\") =', Number('30\n'), ' Number(\"\") =', Number(''));
console.log('Number(\"0x28\") =', Number('0x28'), ' Number(\" 40 \") =', Number(' 40 '), ' Number(\"4_0\") =', Number('4_0'));
console.log('\"2\u{1D7DC}:00\".length =', '2\u{1D7DC}:00'.length, ' [...].length =', [...'2\u{1D7DC}:00'].length);
"

cd /tmp/pr
echo "== class boundary chars =="
for lbl in '/0:30' '30:30' '3:30' '10:/0' '10:60' '10:30:/0' '10:30:60'; do ./cls2.sh "$lbl" "$lbl"; done
echo "== int() with Nd + trailing LF in components =="
perl -e 'use Encode; my $exe="/workspace/dataset/test4_executable";
my @cases=(["10:5<AI9>+LF","10:5".encode("UTF-8",chr(0x669))."\n"],
           ["10:5<AI9>:5<AI9>+LF","10:5".encode("UTF-8",chr(0x669)).":5".encode("UTF-8",chr(0x669))."\n"],
           ["2<AI4>:00+LF","2".encode("UTF-8",chr(0x664)).":00\n"],
           ["1<astral2>:3<astral4>+LF","1".encode("UTF-8",chr(0x1D7D0)).":3".encode("UTF-8",chr(0x1D7D2))."\n"],
           ["10\\n only","10\n"], ["10:30: (dangling)","10:30:"], ["10:30:45:00","10:30:45:00"]);
for my $c (@cases){ my $pid=fork();
  if($pid==0){ open(STDOUT,">","/tmp/pr/qo.txt"); open(STDERR,">","/tmp/pr/qe.txt"); exec {$exe} ($exe,"--a",$c->[1],"--b","x","--c","y"); }
  waitpid($pid,0); my $rc=$?>>8; my $se=do{local $/; open(my $f,"<","/tmp/pr/qe.txt"); <$f>//""};
  my $k = $rc==0?"OK":($se=~/Invalid time format/?"FMT":($se=~/Invalid number of hours/?"HOURS":"OTHER($rc)"));
  printf("%-28s %-6s rc=%d so=%d\n",$c->[0],$k,$rc,(-s "/tmp/pr/qo.txt"));}'

cd /tmp/pr
echo "== invalid UTF-8 / overlong (Python surrogateescape vs Node U+FFFD -> same verdict) =="
perl -e 'my $exe="/workspace/dataset/test4_executable";
my @c=(["2+0xFF",  "2\xff:00"], ["2+0x80","2\x80:00"], ["1+overlong C0 B1","1\xc0\xb1:30"],
       ["1+CESU ED A0 80","1\xed\xa0\x80:30"], ["ff fe","\xff\xfe:00"], ["2+FFFD literal","2\xef\xbf\xbd:00"]);
for my $x (@c){ my $p=fork(); if($p==0){open(STDOUT,">","/tmp/pr/ro.txt");open(STDERR,">","/tmp/pr/re.txt");exec {$exe}($exe,"--a",$x->[1],"--b","x","--c","y");}
 waitpid($p,0); my $rc=$?>>8; my $se=do{local $/;open(my $f,"<","/tmp/pr/re.txt");<$f>//""};
 my $k=$rc==0?"OK":($se=~/Invalid time format/?"FMT":($se=~/Invalid number of hours/?"HOURS":"OTHER($rc)"));
 printf("%-22s %-6s rc=%d so=%d\n",$x->[0],$k,$rc,(-s "/tmp/pr/ro.txt"));}'
echo "== extra Nd blocks, offset 4 (expect HOURS), offset 3 (expect OK) — non-10-aligned starts =="
for cp in 0F20 1040 17E0 A9F0 ABF0 0DE6 1C50 1B50 A620; do
  d4=$(printf '%X' $((0x$cp+4))); d3=$(printf '%X' $((0x$cp+3)))
  perl drv.pl "U+$cp +4 (zero%10=$((0x$cp%10)))" s:2 c:$d4 s::00
  perl drv.pl "U+$cp +3" s:2 c:$d3 s::00
done
